// ServerInterface represents all server handlers.
type ServerInterface interface {
	// ApplyChange Apply a change
	// (POST /changes/apply)
	ApplyChange(c *fiber.Ctx) error
	// PreviewChange Render a change as LDIF and as an Ansible task
	// (POST /changes/preview)
	PreviewChange(c *fiber.Ctx) error
	// ApplyChangeset Apply several changes in order
	// (POST /changeset/apply)
	ApplyChangeset(c *fiber.Ctx) error
	// PreviewChangeset Render several changes as one LDIF document and one playbook
	// (POST /changeset/preview)
	PreviewChangeset(c *fiber.Ctx) error
	// CountEntries Count the entries under a base, up to a limit
	// (GET /count)
	CountEntries(c *fiber.Ctx, params CountEntriesParams) error
	// GetEntry Read one entry
	// (GET /entry)
	GetEntry(c *fiber.Ctx, params GetEntryParams) error
	// ExportLdif Export an entry or a subtree as LDIF
	// (GET /export/ldif)
	ExportLdif(c *fiber.Ctx, params ExportLdifParams) error
	// ParseLdif Parse an LDIF document into change records
	// (POST /import/ldif)
	ParseLdif(c *fiber.Ctx) error
	// GetSchema The whole schema, indexed for browsing
	// (GET /schema)
	GetSchema(c *fiber.Ctx) error
	// GetAttributeType One attribute type, with its cross-links resolved
	// (GET /schema/attributetypes/{name})
	GetAttributeType(c *fiber.Ctx, name string) error
	// BuildSchemaChange Build the modification that installs, replaces or removes a definition
	// (POST /schema/change)
	BuildSchemaChange(c *fiber.Ctx) error
	// GetObjectClass One object class, with its cross-links resolved
	// (GET /schema/objectclasses/{name})
	GetObjectClass(c *fiber.Ctx, name string) error
	// GetRequirements What an entry of these object classes must and may hold
	// (GET /schema/requirements)
	GetRequirements(c *fiber.Ctx, params GetRequirementsParams) error
	// Search Search the directory
	// (POST /search)
	Search(c *fiber.Ctx) error
	// DeleteSession Disconnect
	// (DELETE /session)
	DeleteSession(c *fiber.Ctx) error
	// GetSession Describe the current session
	// (GET /session)
	GetSession(c *fiber.Ctx) error
	// CreateSession Connect and bind to a directory
	// (POST /session)
	CreateSession(c *fiber.Ctx) error
	// ListChildren List the children of an entry
	// (GET /tree)
	ListChildren(c *fiber.Ctx, params ListChildrenParams) error
	// ListObjectViews The object-aware views this directory supports
	// (GET /views)
	ListObjectViews(c *fiber.Ctx) error
}

